let react = require("react");
//#region src/usePrevious/index.ts
function usePrevious(value) {
	const [current, setCurrent] = (0, react.useState)(value);
	const [previous, setPrevious] = (0, react.useState)();
	if (value !== current) {
		setPrevious(current);
		setCurrent(value);
	}
	return previous;
}
//#endregion
exports.usePrevious = usePrevious;
